import React, { useState, useCallback, useEffect } from 'react';
import { Header } from './components/Header';
import { AudioUploader } from './components/AudioUploader';
import { TranscriptionDisplay } from './components/TranscriptionDisplay';
import { SubtitlePreview } from './components/SubtitlePreview';
import { Button } from './components/Button';
import { LoadingSpinner } from './components/LoadingSpinner';
import { ErrorMessage } from './components/ErrorMessage';
import { FileInfo } from './components/FileInfo';
import { ApiKeyWarning } from './components/ApiKeyWarning';
import { AudioPlayer } from './components/AudioPlayer';
import { AudioAnalysisDisplay } from './components/AudioAnalysisDisplay';
import { TranscriptionModeSelector, TranscriptionMode } from './components/TranscriptionModeSelector';
import { MAX_FILE_SIZE_BYTES, SUPPORTED_AUDIO_TYPES, SUPPORTED_AUDIO_EXTENSIONS_DISPLAY, formatBytes } from './constants';
import { transcribeAudioWithGemini, analyzeAudioContent } from './services/geminiService';

type AppState = 'IDLE' | 'API_KEY_MISSING' | 'FILE_SELECTED' | 'LOADING' | 'TRANSCRIBED' | 'ERROR';

const App = () => {
  const [currentFile, setCurrentFile] = useState<File | null>(null);
  const [appState, setAppState] = useState<AppState>('IDLE');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [transcriptionText, setTranscriptionText] = useState<string | null>(null);
  const [apiKeyAvailable, setApiKeyAvailable] = useState<boolean>(true);
  const [audioSrc, setAudioSrc] = useState<string | null>(null);

  // State for transcription mode
  const [transcriptionMode, setTranscriptionMode] = useState<TranscriptionMode>('standard');
  // State for synchronization
  const [audioCurrentTime, setAudioCurrentTime] = useState<number>(0);

  // New state for audio analysis
  const [audioSummary, setAudioSummary] = useState<string | null>(null);
  const [audioCefrLevel, setAudioCefrLevel] = useState<string | null>(null);
  const [audioDurationFormatted, setAudioDurationFormatted] = useState<string | null>(null);

  useEffect(() => {
    let keyIsAvailable = false;
    try {
      if (typeof process !== 'undefined' && 
          typeof process.env !== 'undefined' && 
          process.env.API_KEY && 
          process.env.API_KEY !== "YOUR_API_KEY_HERE" && 
          process.env.API_KEY.trim() !== "") {
        keyIsAvailable = true;
      }
    } catch (e) {
        console.warn("Could not check process.env.API_KEY directly during initial check:", e);
        keyIsAvailable = false; 
    }

    setApiKeyAvailable(keyIsAvailable);
    if (!keyIsAvailable) {
        setAppState('API_KEY_MISSING');
    }
  }, []);

  // Effect for cleaning up audio object URL
  useEffect(() => {
    const currentAudioSrc = audioSrc; 
    return () => {
      if (currentAudioSrc) {
        URL.revokeObjectURL(currentAudioSrc);
      }
    };
  }, [audioSrc]);

  // Effect for calculating audio duration
  useEffect(() => {
    if (audioSrc && currentFile) { 
      const audio = document.createElement('audio');
      if (currentFile.type && SUPPORTED_AUDIO_TYPES.includes(currentFile.type)) {
          const source = document.createElement('source');
          source.src = audioSrc;
          source.type = currentFile.type;
          audio.appendChild(source);
      } else {
          audio.src = audioSrc; 
      }

      const handleLoadedMetadata = () => {
        if (!isNaN(audio.duration) && audio.duration > 0 && audio.duration !== Infinity) {
          const minutes = Math.floor(audio.duration / 60);
          const seconds = Math.floor(audio.duration % 60);
          setAudioDurationFormatted(
            `${minutes}:${seconds.toString().padStart(2, '0')}`
          );
        } else {
          setAudioDurationFormatted("N/A");
        }
        cleanup();
      };
      const handleError = () => {
        console.warn("Error loading audio metadata for duration calculation.");
        setAudioDurationFormatted("N/A");
        cleanup();
      };

      const cleanup = () => {
        audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
        audio.removeEventListener('error', handleError);
        audio.removeAttribute('src'); 
        while (audio.firstChild) { 
            audio.removeChild(audio.firstChild);
        }
        audio.load(); 
      };

      audio.addEventListener('loadedmetadata', handleLoadedMetadata);
      audio.addEventListener('error', handleError);
      audio.preload = 'metadata'; 

      return cleanup; 
    } else {
      setAudioDurationFormatted(null);
    }
  }, [audioSrc, currentFile]);


  const clearAnalysisData = () => {
    setAudioSummary(null);
    setAudioCefrLevel(null);
    setAudioDurationFormatted(null); 
    setAudioCurrentTime(0);
  };

  const handleClearFile = useCallback(() => {
    if (audioSrc) {
      URL.revokeObjectURL(audioSrc);
      setAudioSrc(null);
    }
    setCurrentFile(null);
    setErrorMessage(null);
    setTranscriptionText(null);
    clearAnalysisData();
    setAppState(apiKeyAvailable ? 'IDLE' : 'API_KEY_MISSING');
    const fileInput = document.getElementById('audio-upload') as HTMLInputElement;
    if (fileInput) {
        fileInput.value = '';
    }
  }, [apiKeyAvailable, audioSrc]);

  const handleFileSelect = useCallback((file: File | null) => {
    if (audioSrc) {
        URL.revokeObjectURL(audioSrc);
        setAudioSrc(null);
    }

    setCurrentFile(null); 
    setErrorMessage(null);
    setTranscriptionText(null);
    clearAnalysisData();
    setAppState(apiKeyAvailable ? 'IDLE' : 'API_KEY_MISSING');

    if (!file) {
      return;
    }

    if (!apiKeyAvailable) {
        setAppState('API_KEY_MISSING');
        return;
    }

    if (!SUPPORTED_AUDIO_TYPES.includes(file.type)) {
      setErrorMessage(`Unsupported file type: ${file.type || 'unknown'}. Please upload ${SUPPORTED_AUDIO_EXTENSIONS_DISPLAY}.`);
      setAppState('ERROR');
      return;
    }

    if (file.size > MAX_FILE_SIZE_BYTES) {
      setErrorMessage(`File is too large (${formatBytes(file.size)}). Maximum size is ${formatBytes(MAX_FILE_SIZE_BYTES)}.`);
      setAppState('ERROR');
      return;
    }

    setCurrentFile(file);
    const newAudioSrc = URL.createObjectURL(file);
    setAudioSrc(newAudioSrc); 
    setAppState('FILE_SELECTED');
  }, [apiKeyAvailable, audioSrc]); 


  const handleTranscribe = async () => {
    if (!currentFile) {
      setErrorMessage("No file selected for transcription.");
      setAppState('ERROR');
      return;
    }

    if (!apiKeyAvailable) {
        setAppState('API_KEY_MISSING');
        setErrorMessage("Cannot transcribe: API Key is not configured. Please ensure it's set and refresh.");
        return;
    }

    setAppState('LOADING');
    setErrorMessage(null);
    setTranscriptionText(null);
    setAudioSummary(null);
    setAudioCefrLevel(null);
    setAudioCurrentTime(0);

    try {
      // Pass the selected mode to the service
      const text = await transcribeAudioWithGemini(currentFile, transcriptionMode);
      setTranscriptionText(text);

      if (text && text.trim() !== "") {
        try {
          const analysisResult = await analyzeAudioContent(text);
          setAudioSummary(analysisResult.summary);
          setAudioCefrLevel(analysisResult.cefrLevel);
        } catch (analysisError: any) {
          console.error("Audio content analysis failed:", analysisError);
          setAudioSummary("Could not retrieve summary."); 
          setAudioCefrLevel("Could not retrieve CEFR level."); 
        }
      } else {
        setAudioSummary("Transcription was empty, no analysis performed.");
        setAudioCefrLevel("N/A");
      }
      setAppState('TRANSCRIBED');
    } catch (error: any) {
      console.error("Transcription error in App:", error);
      if (error.message === "API_KEY_MISSING") {
        setApiKeyAvailable(false); 
        setAppState('API_KEY_MISSING');
        setErrorMessage("Transcription failed: Google Gemini API Key is missing, invalid, or there was an issue initializing the service. Please configure it correctly and refresh.");
      } else {
        setErrorMessage(error.message || "An unknown error occurred during transcription.");
        setAppState('ERROR');
      }
      if (audioSrc) {
        URL.revokeObjectURL(audioSrc);
        setAudioSrc(null);
      }
      setCurrentFile(null); 
      clearAnalysisData(); 
    }
  };

  const handleTranscribeAnother = () => {
    handleClearFile();
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 to-slate-700 text-slate-100 flex flex-col items-center p-4 selection:bg-sky-500 selection:text-white">
      <Header />
      <main className="container mx-auto mt-4 p-6 bg-slate-800 shadow-2xl rounded-lg w-full max-w-2xl">

        {appState === 'API_KEY_MISSING' && <ApiKeyWarning />}

        {(appState === 'IDLE' || appState === 'FILE_SELECTED' || appState === 'ERROR') && (
          <AudioUploader 
            onFileSelect={handleFileSelect} 
            disabled={!apiKeyAvailable} 
            currentFile={currentFile} 
          />
        )}

        {appState === 'ERROR' && errorMessage && <ErrorMessage message={errorMessage} />}

        {currentFile && (appState === 'FILE_SELECTED' || appState === 'LOADING' || appState === 'ERROR') && (
          <FileInfo 
            fileName={currentFile.name} 
            fileSize={currentFile.size} 
            onClear={handleClearFile} 
          />
        )}

        {appState === 'FILE_SELECTED' && apiKeyAvailable && (
           <div className="mt-6 flex flex-col items-center">
            {/* Mode Selector */}
            <TranscriptionModeSelector 
              mode={transcriptionMode} 
              onChange={setTranscriptionMode} 
              disabled={!currentFile}
            />

            <Button onClick={handleTranscribe} disabled={!currentFile} className="w-full sm:w-auto">
              {transcriptionMode === 'subtitles' ? 'Generate Subtitles' : 'Transcribe Audio'}
            </Button>
          </div>
        )}

        {appState === 'LOADING' && <LoadingSpinner />}

        {appState === 'TRANSCRIBED' && (
          <>
            <AudioAnalysisDisplay 
              summary={audioSummary}
              audioDuration={audioDurationFormatted}
              cefrLevel={audioCefrLevel}
            />

            {/* Conditional Rendering based on Mode */}
            {transcriptionText && (
              transcriptionMode === 'standard' ? (
                <TranscriptionDisplay 
                  text={transcriptionText} 
                  currentTime={audioCurrentTime} 
                />
              ) : (
                <SubtitlePreview 
                  srtContent={transcriptionText} 
                  fileName={currentFile ? currentFile.name : 'subtitles.srt'}
                  currentTime={audioCurrentTime}
                />
              )
            )}

            {audioSrc && <AudioPlayer src={audioSrc} onTimeUpdate={setAudioCurrentTime} />}
            <div className="mt-8 text-center">
                <Button onClick={handleTranscribeAnother} variant="secondary">
                    Transcribe Another File
                </Button>
            </div>
          </>
        )}

        {appState === 'IDLE' && apiKeyAvailable && !errorMessage && (
            <div className="text-center py-10 text-slate-400">
                <p>Upload an audio file to begin.</p>
                <p className="text-xs mt-2">
                  (Supported: {SUPPORTED_AUDIO_EXTENSIONS_DISPLAY}, Max: {formatBytes(MAX_FILE_SIZE_BYTES)})
                </p>
            </div>
        )}

      </main>
      <footer className="text-center py-8 text-slate-400 text-sm">
        <p>
          <strong className="font-bold text-sky-400">Voice</strong><strong className="font-bold text-yellow-400">Script</strong> - Audio transcription tool powered by Gemini &copy; {new Date().getFullYear()} | <strong className="font-bold">Camilo M.</strong>
        </p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { PlayCircle } from 'lucide-react';

interface AudioPlayerProps {
  src: string;
  onTimeUpdate?: (time: number) => void;
}

export const AudioPlayer = ({ src, onTimeUpdate }: AudioPlayerProps) => {
  if (!src) return null;

  const handleTimeUpdate = (e: React.SyntheticEvent<HTMLAudioElement>) => {
    if (onTimeUpdate) {
      onTimeUpdate(e.currentTarget.currentTime);
    }
  };

  return (
    <div className="mt-8" aria-label="Audio Playback Controls">
      <h3 className="text-xl font-semibold mb-3 text-sky-400 flex items-center">
        <PlayCircle size={24} className="mr-2 flex-shrink-0" />
        Audio Playback
      </h3>
      <div className="bg-slate-900 p-3 sm:p-4 rounded-lg shadow-inner">
        <audio
          controls
          src={src}
          className="w-full"
          preload="metadata"
          onTimeUpdate={handleTimeUpdate}
        >
          Your browser does not support the audio element.
        </audio>
      </div>
    </div>
  );
};

import React, { useMemo, useState, useCallback, useEffect, useRef } from 'react';
import { Type, Copy, Check, Search, ChevronUp, ChevronDown, X } from 'lucide-react';

interface TranscriptionDisplayProps {
  text: string;
  currentTime?: number;
}

interface Match {
  lineIndex: number;
  start: number;
  end: number;
}

// Regex to capture the core time part from various timestamp formats.
const extractTimeRegex = /\s*(\d{1,2}:\d{2}(?::\d{2})?)\s*/;

const formatTimestampString = (rawTimestamp: string): string => {
    const match = rawTimestamp.match(extractTimeRegex);
    if (match && match[1]) {
        if (rawTimestamp.startsWith('(')) return `(${match[1]})`;
        return `[${match[1]}]`;
    }
    return rawTimestamp;
};

const timestampToSeconds = (timestamp: string): number => {
    const match = timestamp.match(/(\d{1,2}):(\d{2})(?::(\d{2}))?/);
    if (!match) return 0;
    const mins = parseInt(match[1], 10);
    const secs = parseInt(match[2], 10);
    const msecs = match[3] ? parseInt(match[3], 10) : 0;
    return mins * 60 + secs + (msecs / 1000);
};

const getSpeakerColorClass = (speakerTag: string): string => {
  const match = speakerTag.match(/Speaker\s*(\d+)\s*:/i);
  if (match && match[1]) {
    const speakerNum = parseInt(match[1], 10);
    switch (speakerNum) {
      case 1: return 'text-sky-300';
      case 2: return 'text-yellow-400';
      case 3: return 'text-green-400';
      case 4: return 'text-pink-400';
      case 5: return 'text-teal-400';
      default: return 'text-sky-300';
    }
  }
  return 'text-sky-300';
};

// Helper to parse a line into its constituent parts (timestamp, speaker, and content)
const lineStartRegex = /^((\[\s*\d{1,2}:\d{2}(?::\d{2})?\s*\]|\(\s*\d{1,2}:\d{2}(?::\d{2})?\s*\))\s*)?((?:Speaker\s*\d*):\s*)?(.*)/i;
const parseLine = (line: string) => {
    const lineMatch = line.match(lineStartRegex);
    if (lineMatch) {
        return {
            rawTimestamp: lineMatch[1] || undefined,
            speakerTag: lineMatch[3] || undefined,
            textContent: lineMatch[4] || '',
        };
    }
    return { rawTimestamp: undefined, speakerTag: undefined, textContent: line };
};

export const TranscriptionDisplay = ({ text, currentTime = 0 }: TranscriptionDisplayProps) => {
  const [copied, setCopied] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [matches, setMatches] = useState<Match[]>([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(-1);
  const activeMatchRef = useRef<HTMLSpanElement>(null);
  const activeLineRef = useRef<HTMLDivElement>(null);

  const lines = useMemo(() => text.split('\n'), [text]);

  // Pre-calculate line start times for highlighting
  const lineStartTimes = useMemo(() => {
    return lines.map(line => {
      const { rawTimestamp } = parseLine(line);
      return rawTimestamp ? timestampToSeconds(rawTimestamp) : null;
    });
  }, [lines]);

  // Determine which line is currently "active" based on audio playback
  const activeLineIndex = useMemo(() => {
    if (currentTime === 0) return -1;

    let lastValidIndex = -1;
    for (let i = 0; i < lineStartTimes.length; i++) {
      const startTime = lineStartTimes[i];
      if (startTime !== null) {
        if (currentTime >= startTime) {
          lastValidIndex = i;
        } else {
          // If current time is less than this start time, the active one is the previous one found
          break;
        }
      } else if (lastValidIndex !== -1) {
          // If this line has no timestamp, it belongs to the previous active one
          // (optional: we could check if it's just an empty line)
      }
    }
    return lastValidIndex;
  }, [currentTime, lineStartTimes]);

  useEffect(() => {
    if (activeLineRef.current && activeLineIndex !== -1) {
        activeLineRef.current.scrollIntoView({
            behavior: 'smooth',
            block: 'center',
        });
    }
  }, [activeLineIndex]);

  useEffect(() => {
    if (!searchQuery) {
      setMatches([]);
      setCurrentMatchIndex(-1);
      return;
    }

    const newMatches: Match[] = [];
    const query = searchQuery.toLowerCase();
    lines.forEach((line, lineIndex) => {
      const { textContent } = parseLine(line);
      const lowerCaseContent = textContent.toLowerCase();
      let startIndex = 0;
      let index;
      while ((index = lowerCaseContent.indexOf(query, startIndex)) > -1) {
        newMatches.push({
          lineIndex,
          start: index,
          end: index + query.length,
        });
        startIndex = index + query.length;
      }
    });

    setMatches(newMatches);
    setCurrentMatchIndex(newMatches.length > 0 ? 0 : -1);
  }, [searchQuery, lines]);

  useEffect(() => {
    if (activeMatchRef.current) {
      activeMatchRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    }
  }, [currentMatchIndex]);

  const handleCopy = useCallback(() => {
    if (text) {
      navigator.clipboard.writeText(text).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      }).catch(err => {
        console.error('Failed to copy text: ', err);
      });
    }
  }, [text]);

  const handleNextMatch = () => {
    if (matches.length > 0) {
      setCurrentMatchIndex((prevIndex) => (prevIndex + 1) % matches.length);
    }
  };

  const handlePrevMatch = () => {
    if (matches.length > 0) {
      setCurrentMatchIndex((prevIndex) => (prevIndex - 1 + matches.length) % matches.length);
    }
  };

  const formattedText = useMemo(() => {
    let matchCounter = -1;
    return lines.map((line, lineIndex) => {
      if (line.trim() === "") {
        return <div key={`line-${lineIndex}`} style={{ minHeight: '1.2em' }} aria-hidden="true"></div>;
      }

      const parts: (string | React.ReactElement)[] = [];
      const { rawTimestamp, speakerTag, textContent } = parseLine(line);
      const isActive = activeLineIndex === lineIndex;

      if (rawTimestamp) {
        const cleanedTimestamp = formatTimestampString(rawTimestamp.trim()); 
        parts.push(
          <span key={`leadts-${lineIndex}`} className={`px-1 py-0.5 rounded-sm font-medium mx-0.5 transition-colors duration-300 ${isActive ? 'bg-sky-400 text-slate-900 shadow-sm' : 'text-neutral-300 bg-black/30'}`}>
            {cleanedTimestamp}
          </span>
        );
      }
      if (speakerTag) {
        const speakerColorClass = getSpeakerColorClass(speakerTag);
        parts.push(<strong key={`spk-${lineIndex}`} className={`font-semibold transition-opacity duration-300 ${speakerColorClass} ${isActive ? 'opacity-100' : 'opacity-80'}`}>{speakerTag}</strong>);
      }

      const lineMatches = matches.filter(m => m.lineIndex === lineIndex).sort((a, b) => a.start - b.start);
      let lastIndex = 0;

      if (lineMatches.length > 0 && searchQuery) {
        lineMatches.forEach(match => {
          if (match.start > lastIndex) {
            parts.push(textContent.substring(lastIndex, match.start));
          }
          matchCounter++;
          const isCurrent = matchCounter === currentMatchIndex;
          parts.push(
            <mark
              key={`match-${lineIndex}-${match.start}`}
              ref={isCurrent ? activeMatchRef : null}
              className={`rounded px-0.5 py-0 ${isCurrent ? 'bg-yellow-400 text-black font-bold ring-2 ring-yellow-200' : 'bg-sky-500/40 text-white'}`}
            >
              {textContent.substring(match.start, match.end)}
            </mark>
          );
          lastIndex = match.end;
        });
      }

      if (lastIndex < textContent.length) {
        parts.push(textContent.substring(lastIndex));
      }

      return (
        <div 
            key={`line-${lineIndex}`} 
            ref={isActive ? activeLineRef : null}
            className={`min-h-[1.2em] transition-all duration-300 rounded px-1 -mx-1 ${isActive ? 'bg-sky-500/10 border-l-2 border-sky-400' : 'border-l-2 border-transparent'}`}
        >
          {parts.map((part, partIndex) => (
            <React.Fragment key={partIndex}>{part}</React.Fragment>
          ))}
        </div>
      );
    });
  }, [lines, matches, currentMatchIndex, searchQuery, activeLineIndex]);

  return (
    <div className="mt-8">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-3 gap-3">
        <h2 className="text-2xl font-semibold text-sky-400 flex items-center">
          <Type size={28} className="mr-3" />
          Transcription Result
        </h2>
        <div className="w-full sm:w-auto flex items-center gap-2 bg-slate-700/50 rounded-lg p-1.5">
          <div className="relative flex-grow">
            <Search size={18} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            <input
              type="text"
              placeholder="Search transcription..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-slate-800 border border-slate-600 rounded-md pl-9 pr-8 py-1.5 text-sm text-slate-200 placeholder-slate-400 focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none"
            />
            {searchQuery && (
              <button onClick={() => setSearchQuery('')} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white">
                <X size={18} />
              </button>
            )}
          </div>
          {searchQuery && (
            <div className="flex items-center text-sm text-slate-300 flex-shrink-0">
              <span>{matches.length > 0 ? currentMatchIndex + 1 : 0} of {matches.length}</span>
              <button onClick={handlePrevMatch} disabled={matches.length === 0} className="p-1.5 rounded-md hover:bg-slate-600 disabled:opacity-50 disabled:cursor-not-allowed">
                <ChevronUp size={16} />
              </button>
              <button onClick={handleNextMatch} disabled={matches.length === 0} className="p-1.5 rounded-md hover:bg-slate-600 disabled:opacity-50 disabled:cursor-not-allowed">
                <ChevronDown size={16} />
              </button>
            </div>
          )}
          <button
              onClick={handleCopy}
              title={copied ? "Copied!" : "Copy transcription"}
              className="p-1.5 rounded-md hover:bg-slate-600 text-slate-400 hover:text-sky-400 focus:outline-none focus:ring-2 focus:ring-sky-500 focus:ring-opacity-50 transition-colors flex-shrink-0"
              aria-label={copied ? "Transcription copied to clipboard" : "Copy transcription to clipboard"}
              aria-live="polite"
          >
              {copied ? <Check size={20} className="text-green-400" /> : <Copy size={20} />}
          </button>
        </div>
      </div>
      <div className="bg-slate-900 p-4 sm:p-6 rounded-lg shadow-inner max-h-[50vh] sm:max-h-[60vh] overflow-y-auto scroll-smooth">
        <div className="text-slate-300 text-sm sm:text-base leading-relaxed break-words font-mono selection:bg-amber-500 selection:text-black">
            {formattedText}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Download, Check, FileCode } from 'lucide-react';
import { Button } from './Button';

interface SubtitlePreviewProps {
  srtContent: string;
  fileName: string;
  currentTime?: number;
}

interface SrtBlock {
    id: string;
    startTime: number;
    endTime: number;
    text: string;
    raw: string;
}

const parseSrtTimestamp = (timestamp: string): number => {
    const match = timestamp.match(/(\d{2}):(\d{2}):(\d{2}),(\d{3})/);
    if (!match) return 0;
    const hours = parseInt(match[1], 10);
    const mins = parseInt(match[2], 10);
    const secs = parseInt(match[3], 10);
    const msecs = parseInt(match[4], 10);
    return hours * 3600 + mins * 60 + secs + msecs / 1000;
};

export const SubtitlePreview = ({ srtContent, fileName, currentTime = 0 }: SubtitlePreviewProps) => {
  const [downloaded, setDownloaded] = useState(false);
  const activeBlockRef = useRef<HTMLDivElement>(null);

  const srtBlocks = useMemo(() => {
    const blocks: SrtBlock[] = [];
    const rawBlocks = srtContent.trim().split(/\n\s*\n/);

    rawBlocks.forEach((block) => {
        const lines = block.split('\n');
        if (lines.length >= 2) {
            const id = lines[0].trim();
            const timeMatch = lines[1].match(/(\d{2}:\d{2}:\d{2},\d{3})\s*-->\s*(\d{2}:\d{2}:\d{2},\d{3})/);
            if (timeMatch) {
                const startTime = parseSrtTimestamp(timeMatch[1]);
                const endTime = parseSrtTimestamp(timeMatch[2]);
                const text = lines.slice(2).join('\n');
                blocks.push({ id, startTime, endTime, text, raw: block });
            }
        }
    });
    return blocks;
  }, [srtContent]);

  const activeBlockId = useMemo(() => {
    const active = srtBlocks.find(b => currentTime >= b.startTime && currentTime <= b.endTime);
    return active ? active.id : null;
  }, [currentTime, srtBlocks]);

  useEffect(() => {
    if (activeBlockRef.current && activeBlockId !== null) {
        activeBlockRef.current.scrollIntoView({
            behavior: 'smooth',
            block: 'center',
        });
    }
  }, [activeBlockId]);

  const handleDownload = () => {
    const contentToSave = srtContent.trim() + '\n\n';
    const blob = new Blob([contentToSave], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    const baseName = fileName.substring(0, fileName.lastIndexOf('.')) || fileName;
    a.download = `${baseName}.srt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    setDownloaded(true);
    setTimeout(() => setDownloaded(false), 3000);
  };

  return (
    <div className="mt-8">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-3 gap-3">
        <h2 className="text-2xl font-semibold text-yellow-400 flex items-center">
          <FileCode size={28} className="mr-3" />
          Subtitle Preview (.srt)
        </h2>
        <div>
            <Button onClick={handleDownload} className="!bg-yellow-500 hover:!bg-yellow-600 focus:!ring-yellow-400 py-2 px-4 text-sm flex items-center gap-2 text-slate-900">
                {downloaded ? <Check size={18} /> : <Download size={18} />}
                {downloaded ? 'Downloaded' : 'Download .srt File'}
            </Button>
        </div>
      </div>
      <div className="bg-slate-900 p-4 rounded-lg shadow-inner border border-slate-700 max-h-[50vh] sm:max-h-[60vh] overflow-y-auto scroll-smooth">
        <div className="space-y-4">
            {srtBlocks.map((block) => (
                <div 
                    key={block.id} 
                    ref={activeBlockId === block.id ? activeBlockRef : null}
                    className={`p-3 rounded-lg transition-all duration-300 font-mono text-sm sm:text-base ${
                        activeBlockId === block.id 
                        ? 'bg-yellow-400/20 border-l-4 border-yellow-400 shadow-[0_0_15px_rgba(250,204,21,0.1)]' 
                        : 'bg-slate-800/40 border-l-4 border-transparent text-slate-400'
                    }`}
                >
                    <div className="flex justify-between items-center mb-1 text-xs opacity-60">
                        <span>#{block.id}</span>
                        <span className={activeBlockId === block.id ? 'text-yellow-400 font-bold' : ''}>
                            {block.raw.split('\n')[1]}
                        </span>
                    </div>
                    <pre className={`whitespace-pre-wrap transition-colors duration-300 ${activeBlockId === block.id ? 'text-white font-semibold' : 'text-slate-400'}`}>
                        {block.text}
                    </pre>
                </div>
            ))}
            {srtBlocks.length === 0 && (
                <pre className="text-slate-300 text-sm font-mono whitespace-pre-wrap p-2">
                    {srtContent}
                </pre>
            )}
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, GenerateContentResponse, Part, Type } from "@google/genai";
import { SUPPORTED_AUDIO_TYPES } from '../constants';

// Store the initialized client to avoid re-initializing if the key is valid
let ai: GoogleGenAI | null = null;
let apiKeyInitializationError: string | null = null;

export type TranscriptionMode = 'standard' | 'subtitles';

function initializeAiClient(): GoogleGenAI {
  if (apiKeyInitializationError) {
    throw new Error(apiKeyInitializationError);
  }
  if (ai) {
    return ai;
  }

  let apiKey: string | undefined;
  try {
    if (typeof process !== 'undefined' && typeof process.env !== 'undefined') {
      apiKey = process.env.API_KEY;
    }
  } catch (e) {
    console.warn("Error accessing process.env.API_KEY:", e);
    apiKeyInitializationError = "API_KEY_ACCESS_ERROR";
    throw new Error(apiKeyInitializationError);
  }

  if (!apiKey || apiKey === "YOUR_API_KEY_HERE" || apiKey.trim() === "") {
    apiKeyInitializationError = "API_KEY_MISSING";
    throw new Error(apiKeyInitializationError);
  }

  try {
    ai = new GoogleGenAI({ apiKey });
    return ai;
  } catch (error: any) {
    console.error("Failed to initialize GoogleGenAI client:", error);
    apiKeyInitializationError = `Failed to initialize Gemini client: ${error.message || 'Unknown error'}`;
    throw new Error(apiKeyInitializationError);
  }
}


async function fileToGenerativePart(file: File): Promise<Part> {
  if (!SUPPORTED_AUDIO_TYPES.includes(file.type)) {
    throw new Error(`Unsupported audio file type: ${file.type}. Please use one of the supported types.`);
  }

  const base64EncodedString = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = (error) => reject(error);
    reader.readAsDataURL(file);
  });

  return {
    inlineData: {
      mimeType: file.type,
      data: base64EncodedString,
    },
  };
}

export async function transcribeAudioWithGemini(audioFile: File, mode: TranscriptionMode = 'standard'): Promise<string> {
  try {
    const client = initializeAiClient(); 

    const audioPart = await fileToGenerativePart(audioFile);

    let promptText = "";

    if (mode === 'subtitles') {
        promptText = `Generate subtitles for the audio in SubRip Subtitle (SRT) format.
Rules:
1. Format must be strictly SRT (Sequence number, Timecode --> Timecode, Text).
2. Timecodes must be in HH:MM:SS,mmm format.
3. CRITICAL: Prevent timestamp overlap. The Start Time of a subtitle must be strictly greater than the End Time of the preceding subtitle. Leave a small gap (e.g., 50ms) between subtitles to ensure players like YouTube accept them.
4. Ensure extremely precise synchronization with the audio speech.
5. Limit line length to 42 characters max.
6. Max 2 lines per subtitle block.
7. Split sentences naturally at pauses or logical grammatical points. Avoid "orphans" (single words on a line) where possible.
8. Do not include speaker labels unless absolutely necessary for clarity (e.g. multiple off-screen speakers).
9. Output ONLY the raw SRT content. Do not include markdown code blocks, explanations, or any preamble.
10. Ensure each subtitle block is separated by exactly one blank line.
11. Use plain text only and standard UTF-8 friendly punctuation.`;
    } else {
        // Standard transcription prompt
        promptText = `Transcribe the audio. For each speaker's utterance:
1. Start every new speaker turn OR any significant new sentence/phrase with a timestamp in [MM:SS] format (e.g., [00:23]).
2. If it's a new speaker, follow the timestamp with a generic speaker label in the format "Speaker N:" (e.g., "Speaker 1:", "Speaker 2:").
3. For long utterances by the same speaker, insert a fresh [MM:SS] timestamp every 10-15 seconds at the start of the next sentence to facilitate audio synchronization.
4. Provide the transcribed text for that specific segment.
Example:
[00:00] Speaker 1: Good morning everyone.
[00:05] Today we will discuss the future of AI.
[00:12] Speaker 2: That sounds like a fascinating topic.
Prioritize content accuracy and frequent timestamping. Ensure the output is plain text and well-formatted.`;
    }

    const textPromptPart: Part = { text: promptText };

    const contents = { parts: [audioPart, textPromptPart] };

    console.log(`Sending transcription request to Gemini API with model gemini-2.5-flash (Mode: ${mode})`);

    const response: GenerateContentResponse = await client.models.generateContent({
        model: 'gemini-2.5-flash',
        contents,
    });

    let transcription = response.text;

    if (transcription) {
        transcription = transcription.replace(/^```(srt)?\s*/i, '').replace(/```\s*$/, '');
    }

    if (!transcription || transcription.trim() === "") {
        console.warn("Gemini API returned an empty transcription.");
        throw new Error("The model returned an empty transcription. The audio might be silent or unclear.");
    }
    return transcription;

  } catch (error: any) {
    console.error("Error transcribing audio with Gemini:", error);
    if (error.message === "API_KEY_MISSING" || error.message === "API_KEY_ACCESS_ERROR" || (error.message && error.message.includes("API key not valid"))) {
        throw new Error("API_KEY_MISSING");
    }
    const message = error.message || "An unknown error occurred during transcription.";
    if (message.includes("quota")) {
        throw new Error("Transcription failed due to API quota limits. Please check your Gemini API billing and usage.");
    }
    if (message.includes("deadline exceeded") || message.includes("unavailable")) {
        throw new Error("The transcription service is temporarily unavailable or the request timed out. Please try again later.");
    }
    if (message.includes("Failed to initialize Gemini client")) {
        throw new Error(message);
    }
    throw new Error(`Transcription failed: ${message}`);
  }
}

interface AudioAnalysisResult {
  summary: string;
  cefrLevel: string;
}

export async function analyzeAudioContent(transcriptionText: string): Promise<AudioAnalysisResult> {
  try {
    const client = initializeAiClient();

    const analysisPrompt = `Analyze the following audio transcription. Provide:
1.  A concise summary of the content (2-3 sentences).
2.  An estimated CEFR level (e.g., A1, A2, B1, B2, C1, C2) based on the language complexity, vocabulary, and grammar.

Transcription:
---
${transcriptionText}
---`;

    console.log("Sending analysis request to Gemini API with model gemini-2.5-flash");

    const response: GenerateContentResponse = await client.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: {
              type: Type.STRING,
              description: 'A concise summary of the content (2-3 sentences).',
            },
            cefrLevel: {
              type: Type.STRING,
              description: 'An estimated CEFR level (e.g., A1, A2, B1, B2, C1, C2) based on the language complexity, vocabulary, and grammar.',
            },
          },
          required: ["summary", "cefrLevel"],
        },
      },
    });

    let jsonStr = response.text.trim();

    try {
      const parsedData = JSON.parse(jsonStr) as Partial<AudioAnalysisResult>;
      if (typeof parsedData.summary === 'string' && typeof parsedData.cefrLevel === 'string') {
        return { summary: parsedData.summary, cefrLevel: parsedData.cefrLevel };
      } else {
        console.error("Parsed JSON for analysis is missing required fields:", parsedData);
        throw new Error("Analysis response from model was incomplete or malformed (missing summary or cefrLevel).");
      }
    } catch (e) {
      console.error("Failed to parse JSON analysis response:", e, "Raw response:", jsonStr);
      throw new Error("Failed to parse analysis data from the model. The format was unexpected.");
    }

  } catch (error: any) {
    console.error("Error analyzing audio content with Gemini:", error);
     if (error.message === "API_KEY_MISSING" || error.message === "API_KEY_ACCESS_ERROR" || (error.message && error.message.includes("API key not valid"))) {
        throw new Error("API_KEY_MISSING");
    }
    const message = error.message || "An unknown error occurred during audio analysis.";
     if (message.includes("quota")) {
        throw new Error("Audio analysis failed due to API quota limits.");
    }
    if (message.includes("deadline exceeded") || message.includes("unavailable")) {
        throw new Error("The analysis service is temporarily unavailable or the request timed out.");
    }
    throw new Error(`Audio analysis failed: ${message}`);
  }
}
